def exact_tile(shape,S):
    shape=[tuple(x) for x in shape]
    S=set(S); occs=[]
    for (r,c) in S:
        if all((r+dr,c+dc) in S for dr,dc in shape): occs.append((r,c,shape))
    # greedy/DP
    import functools
    occmap={}
    for r,c in S:
        occmap[(r,c)]=[(frozenset((r+dr,c+dc) for dr,dc in shape)) for shape in [] ]
    occsets=[]
    for (r,c) in S:
        if all((r+dr,c+dc) in S for dr,dc in shape):
            occsets.append(frozenset((r+dr,c+dc) for dr,dc in shape))
    def solve(rem, used):
        if not rem: return used
        cell=min(rem)
        for o in occsets:
            if cell in o and o<=rem:
                res=solve(rem-o, used+[o])
                if res: return res
        return None
    res=solve(frozenset(S),[])
    return res
